/**
 * Mobile surface stylesheet, shipped as a string and injected at boot (the
 * standalone page has no CSS-module pipeline).
 */
export declare const mobileCss = "/* Mobile surface chrome: standalone stylesheet (no main-UI design tokens \u2014\n   this page boots without the shell). Light-first palette; the dark palette\n   applies only when the header toggle sets [data-theme='dark']. */\n\n:root {\n  --m-bg: #f3f5f9;\n  --m-bg-raised: #ffffff;\n  --m-bg-input: #ffffff;\n  --m-border: #dfe4ec;\n  --m-text: #1c2333;\n  --m-text-secondary: #4d5768;\n  --m-text-tertiary: #8b95a7;\n  --m-accent: #2f6fed;\n  --m-accent-soft: rgba(47, 111, 237, 0.12);\n  --m-danger: #d64545;\n  --m-success: #1e9e6a;\n  --m-radius: 12px;\n  --m-shadow: 0 1px 2px rgba(16, 24, 40, 0.06);\n  --m-shadow-raise: 0 6px 20px rgba(16, 24, 40, 0.1);\n  --m-backdrop: rgba(15, 23, 42, 0.4);\n}\n\n:root[data-theme='dark'] {\n  --m-bg: #111418;\n  --m-bg-raised: #1a1f26;\n  --m-bg-input: #20262e;\n  --m-border: #2b333d;\n  --m-text: #e8eaed;\n  --m-text-secondary: #9aa3ad;\n  --m-text-tertiary: #6b747f;\n  --m-accent: #4f8cff;\n  --m-accent-soft: rgba(79, 140, 255, 0.14);\n  --m-danger: #e5534b;\n  --m-success: #3fb68b;\n  --m-radius: 12px;\n  --m-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);\n  --m-shadow-raise: 0 6px 20px rgba(0, 0, 0, 0.4);\n  --m-backdrop: rgba(0, 0, 0, 0.55);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml,\nbody {\n  margin: 0;\n  padding: 0;\n  height: 100%;\n  background: var(--m-bg);\n  color: var(--m-text);\n  font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Segoe UI', sans-serif;\n  font-size: 15px;\n  line-height: 1.5;\n  -webkit-text-size-adjust: 100%;\n}\n\n/* The app fills exactly one viewport: the page itself never scrolls, each\n   view owns its scroll region (chat history, session lists) and the chat\n   composer stays pinned to the bottom of the screen. */\n#root {\n  height: 100dvh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.mobile {\n  min-height: 0;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n/* \u2500\u2500 header \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.mobile-header {\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: calc(env(safe-area-inset-top, 0px) + 12px) 16px 10px;\n  background: color-mix(in srgb, var(--m-bg) 88%, transparent);\n  backdrop-filter: blur(10px);\n  border-bottom: 1px solid var(--m-border);\n}\n\n.mobile-title {\n  margin: 0;\n  font-size: 17px;\n  font-weight: 600;\n}\n\n.mobile-titleInline {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.mobile-back {\n  flex: none;\n  width: 32px;\n  height: 32px;\n  border: none;\n  border-radius: 50%;\n  background: transparent;\n  color: var(--m-text);\n  font-size: 22px;\n  line-height: 1;\n  cursor: pointer;\n  transition: background-color 0.12s ease, box-shadow 0.12s ease;\n}\n\n.mobile-back:active {\n  background: var(--m-bg-raised);\n}\n\n.mobile-back:focus-visible {\n  outline: none;\n  box-shadow: 0 0 0 2px var(--m-bg), 0 0 0 4px var(--m-accent);\n}\n\n.mobile-theme-toggle {\n  flex: none;\n  margin-left: auto;\n  width: 32px;\n  height: 32px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: 50%;\n  background: transparent;\n  color: var(--m-text-secondary);\n  cursor: pointer;\n  transition: background-color 0.12s ease, color 0.12s ease, box-shadow 0.12s ease;\n}\n\n.mobile-theme-toggle:active {\n  background: var(--m-bg-raised);\n}\n\n.mobile-theme-toggle:focus-visible {\n  outline: none;\n  box-shadow: 0 0 0 2px var(--m-bg), 0 0 0 4px var(--m-accent);\n}\n\n.mobile-theme-toggle svg {\n  width: 18px;\n  height: 18px;\n}\n\n/* \u2500\u2500 lists \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.mobile-list {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  list-style: none;\n  margin: 0;\n  padding: 8px 0 calc(env(safe-area-inset-bottom, 0px) + 16px);\n}\n\n.mobile-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: calc(100% - 24px);\n  margin: 0 12px 8px;\n  padding: 13px 14px;\n  border: 1px solid var(--m-border);\n  border-radius: 14px;\n  background: var(--m-bg-raised);\n  box-shadow: var(--m-shadow);\n  color: var(--m-text);\n  text-align: left;\n  cursor: pointer;\n}\n\n.mobile-row:active {\n  background: color-mix(in srgb, var(--m-text) 5%, var(--m-bg-raised));\n}\n\n.mobile-rowMain {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n}\n\n.mobile-rowTitle {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 15px;\n}\n\n.mobile-rowMeta {\n  flex: none;\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n}\n\n.mobile-chevron {\n  flex: none;\n  color: var(--m-text-tertiary);\n  font-size: 18px;\n}\n\n.mobile-live {\n  margin-left: 6px;\n  color: var(--m-success);\n  font-size: 10px;\n  vertical-align: middle;\n}\n\n/* \u2500\u2500 empty / error states \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.mobile-empty {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  padding: 32px;\n}\n\n.mobile-muted {\n  margin: 0;\n  color: var(--m-text-tertiary);\n}\n\n.mobile-error {\n  margin: 0;\n  color: var(--m-danger);\n}\n\n.mobile-pad {\n  padding: 8px 16px;\n}\n\n/* \u2500\u2500 buttons \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.mobile-button {\n  height: 38px;\n  padding: 0 18px;\n  border: 1px solid var(--m-border);\n  border-radius: 10px;\n  background: var(--m-bg-raised);\n  color: var(--m-text);\n  font-size: 14px;\n  cursor: pointer;\n}\n\n.mobile-button:disabled {\n  opacity: 0.5;\n}\n\n.mobile-block {\n  display: block;\n  width: calc(100% - 32px);\n  margin: 4px 16px;\n}\n\n/* Primary action (create session): accent fill, readable on both themes. */\n.mobile-new {\n  display: block;\n  width: 100%;\n  height: 44px;\n  border: none;\n  border-radius: 12px;\n  background: linear-gradient(135deg, var(--m-accent) 0%, #4c8dff 100%);\n  color: #fff;\n  font-size: 15px;\n  font-weight: 600;\n  cursor: pointer;\n  box-shadow: 0 2px 8px rgba(47, 111, 237, 0.3);\n}\n\n.mobile-new:active {\n  opacity: 0.88;\n}\n\n.mobile-new:disabled {\n  opacity: 0.6;\n}\n\n.mobile-hint {\n  display: block;\n  margin-top: 2px;\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n}\n\n/* \u2500\u2500 chat \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.chat {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n}\n\n.chat-scroll {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px 14px calc(env(safe-area-inset-bottom, 0px) + 12px);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.chat-msg {\n  max-width: 88%;\n  padding: 10px 12px;\n  border-radius: var(--m-radius);\n  font-size: 14.5px;\n  line-height: 1.55;\n  overflow-wrap: break-word;\n  white-space: pre-wrap;\n}\n\n.chat-msg-user {\n  align-self: flex-end;\n  background: linear-gradient(135deg, var(--m-accent) 0%, #4c8dff 100%);\n  color: #fff;\n  border-bottom-right-radius: 4px;\n  box-shadow: 0 1px 3px rgba(47, 111, 237, 0.28);\n}\n\n.chat-msg-assistant {\n  align-self: flex-start;\n  background: var(--m-bg-raised);\n  border: 1px solid var(--m-border);\n  border-bottom-left-radius: 4px;\n  box-shadow: var(--m-shadow);\n}\n\n.chat-msg-pending .chat-msg-text::after {\n  content: '\u258D';\n  animation: chat-blink 1s steps(2) infinite;\n}\n\n@keyframes chat-blink {\n  50% {\n    opacity: 0;\n  }\n}\n\n.chat-msg-failed {\n  border-color: var(--m-danger);\n}\n\n.chat-msg-failtag {\n  display: inline-block;\n  margin-top: 6px;\n  padding: 1px 8px;\n  border: 1px solid var(--m-danger);\n  border-radius: 999px;\n  color: var(--m-danger);\n  font-size: 11px;\n}\n\n.chat-msg-time {\n  display: block;\n  margin-top: 4px;\n  color: var(--m-text-tertiary);\n  font-size: 10.5px;\n  line-height: 1.2;\n}\n\n.chat-msg-toggle {\n  display: block;\n  margin-top: 8px;\n  padding: 4px 0;\n  border: none;\n  background: transparent;\n  color: var(--m-accent);\n  font-size: 13px;\n  cursor: pointer;\n}\n\n/* Assistant markdown content (GFM subset; renderer in markdown.ts). */\n.chat-md {\n  white-space: normal;\n}\n.chat-md-collapsed {\n  max-height: 45vh;\n  overflow: hidden;\n  position: relative;\n}\n.chat-md-collapsed::after {\n  content: '';\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  height: 28px;\n  background: linear-gradient(transparent, var(--m-bg-raised));\n  pointer-events: none;\n}\n.chat-md-body p { margin: 0 0 8px; }\n.chat-md-body p:last-child { margin-bottom: 0; }\n.chat-md-body h1, .chat-md-body h2, .chat-md-body h3,\n.chat-md-body h4, .chat-md-body h5, .chat-md-body h6 {\n  margin: 12px 0 6px;\n  font-weight: 650;\n  line-height: 1.3;\n}\n.chat-md-body h1 { font-size: 1.35em; }\n.chat-md-body h2 { font-size: 1.25em; }\n.chat-md-body h3 { font-size: 1.15em; }\n.chat-md-body h4, .chat-md-body h5, .chat-md-body h6 { font-size: 1.05em; }\n.chat-md-body code {\n  font-family: var(--m-mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace);\n  font-size: 0.9em;\n  background: var(--m-accent-soft);\n  padding: 1px 5px;\n  border-radius: 4px;\n}\n.chat-md-body pre {\n  margin: 8px 0;\n  padding: 10px;\n  background: #101726;\n  color: #dbe4f5;\n  border-radius: 8px;\n  overflow-x: auto;\n  font-size: 12.5px;\n  line-height: 1.5;\n}\n.chat-md-body pre code {\n  background: transparent;\n  padding: 0;\n  color: inherit;\n}\n.chat-md-body ul, .chat-md-body ol { margin: 4px 0 8px; padding-left: 22px; }\n.chat-md-body li { margin: 2px 0; }\n.chat-md-body blockquote {\n  margin: 8px 0;\n  padding: 4px 10px;\n  border-left: 3px solid var(--m-accent);\n  background: var(--m-accent-soft);\n  border-radius: 0 6px 6px 0;\n  color: var(--m-text-secondary);\n}\n.chat-md-body table {\n  margin: 8px 0;\n  border-collapse: collapse;\n  display: block;\n  overflow-x: auto;\n  font-size: 13px;\n}\n.chat-md-body th, .chat-md-body td {\n  border: 1px solid var(--m-border);\n  padding: 4px 8px;\n}\n.chat-md-body th { background: var(--m-accent-soft); }\n.chat-md-body a { color: var(--m-accent); }\n.chat-md-body hr { border: none; border-top: 1px solid var(--m-border); margin: 10px 0; }\n.chat-md-body img { max-width: 100%; border-radius: 8px; }\n\n/* \u2500\u2500 message disclosures (reasoning / tools) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.chat-disclosure {\n  margin-bottom: 8px;\n  border: 1px solid var(--m-border);\n  border-radius: 10px;\n  background: color-mix(in srgb, var(--m-bg) 55%, transparent);\n  overflow: hidden;\n}\n\n.chat-disclosure-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  width: 100%;\n  padding: 7px 10px;\n  border: none;\n  background: transparent;\n  color: var(--m-text);\n  font-size: 12.5px;\n  text-align: left;\n  cursor: pointer;\n  white-space: nowrap;\n}\n\n.chat-disclosure-caret {\n  flex: none;\n  color: var(--m-text-tertiary);\n  font-size: 14px;\n  line-height: 1;\n  transition: transform 0.15s ease;\n}\n\n.chat-disclosure-open .chat-disclosure-caret {\n  transform: rotate(90deg);\n}\n\n.chat-disclosure-label {\n  flex: none;\n  color: var(--m-text-secondary);\n}\n\n.chat-reasoning[data-pending] .chat-disclosure-label {\n  color: var(--m-accent);\n}\n\n.chat-disclosure-summary {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n}\n\n.chat-disclosure-count {\n  flex: none;\n  color: var(--m-text-tertiary);\n  font-size: 11px;\n}\n\n.chat-disclosure-body {\n  padding: 8px 10px 10px;\n  border-top: 1px dashed var(--m-border);\n  color: var(--m-text-secondary);\n  font-size: 12.5px;\n  line-height: 1.6;\n  overflow-wrap: break-word;\n  white-space: pre-wrap;\n  max-height: 40vh;\n  overflow-y: auto;\n}\n\n.chat-tools-body {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.chat-tool-item {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.chat-tool-name {\n  color: var(--m-text);\n  font-size: 12.5px;\n  font-weight: 600;\n}\n\n.chat-tool-args {\n  margin: 0;\n  padding: 6px 8px;\n  border-radius: 6px;\n  background: var(--m-bg-input);\n  color: var(--m-text-secondary);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 11px;\n  line-height: 1.5;\n  overflow-wrap: break-word;\n  white-space: pre-wrap;\n}\n\n/* \u2500\u2500 composer toolbar (model / permission chips) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.chat-tools {\n  display: flex;\n  gap: 8px;\n  padding: 6px 12px 0;\n}\n\n.chat-chip {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  height: 32px;\n  padding: 0 10px;\n  border: 1px solid var(--m-border);\n  border-radius: 999px;\n  background: var(--m-bg-raised);\n  box-shadow: var(--m-shadow);\n  color: var(--m-text);\n  font-size: 12px;\n  cursor: pointer;\n}\n\n.chat-chip:active {\n  border-color: var(--m-accent);\n  background: var(--m-accent-soft);\n}\n\n.chat-chip-label {\n  flex: none;\n  color: var(--m-text-tertiary);\n}\n\n.chat-chip-value {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.chat-chip-chevron {\n  flex: none;\n  color: var(--m-text-tertiary);\n  font-size: 14px;\n}\n\n/* \u2500\u2500 bottom sheets \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.sheet-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 50;\n  display: flex;\n  flex-direction: column;\n  justify-content: flex-end;\n  background: var(--m-backdrop);\n  animation: sheet-fade 0.18s ease;\n}\n\n@keyframes sheet-fade {\n  from {\n    opacity: 0;\n  }\n  to {\n    opacity: 1;\n  }\n}\n\n.sheet {\n  max-height: 74dvh;\n  display: flex;\n  flex-direction: column;\n  background: var(--m-bg-raised);\n  border: 1px solid var(--m-border);\n  border-bottom: none;\n  border-radius: 16px 16px 0 0;\n  box-shadow: var(--m-shadow-raise);\n  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 10px);\n  animation: sheet-up 0.22s ease;\n}\n\n@keyframes sheet-up {\n  from {\n    transform: translateY(40px);\n    opacity: 0.6;\n  }\n  to {\n    transform: translateY(0);\n    opacity: 1;\n  }\n}\n\n.sheet-handle {\n  flex: none;\n  align-self: center;\n  width: 36px;\n  height: 4px;\n  margin: 8px 0 4px;\n  border-radius: 999px;\n  background: var(--m-border);\n}\n\n.sheet-title {\n  flex: none;\n  padding: 6px 16px 10px;\n  font-size: 15px;\n  font-weight: 600;\n}\n\n.sheet-body {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 0 12px 8px;\n}\n\n.sheet-status {\n  padding: 18px 8px;\n  color: var(--m-text-tertiary);\n  font-size: 13px;\n  text-align: center;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n}\n\n.sheet-status-error {\n  color: var(--m-danger);\n}\n\n.sheet-hint {\n  margin: 0;\n  color: var(--m-text-secondary);\n  font-size: 12px;\n  line-height: 1.5;\n  max-width: 32em;\n}\n\n.sheet-error {\n  margin: 0 0 8px;\n  color: var(--m-danger);\n  font-size: 12.5px;\n}\n\n.sheet-section {\n  margin-bottom: 14px;\n}\n\n.sheet-section-title {\n  padding: 4px 8px 6px;\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n  font-weight: 600;\n}\n\n.sheet-option {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  padding: 10px 12px;\n  border: 1px solid transparent;\n  border-radius: 10px;\n  background: transparent;\n  color: var(--m-text);\n  text-align: left;\n  cursor: pointer;\n}\n\n.sheet-option:active {\n  background: var(--m-bg-input);\n}\n\n.sheet-option-selected {\n  border-color: var(--m-accent);\n  background: color-mix(in srgb, var(--m-accent) 12%, transparent);\n}\n\n.sheet-option:disabled {\n  opacity: 0.5;\n}\n\n.sheet-option-copy {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.sheet-option-title {\n  font-size: 14px;\n}\n\n.sheet-option-desc {\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n  line-height: 1.4;\n}\n\n.sheet-option-check {\n  flex: none;\n  color: var(--m-accent);\n  font-size: 15px;\n  font-weight: 700;\n}\n\n.sheet-confirm-desc {\n  margin: 0 4px 14px;\n  color: var(--m-text-secondary);\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.sheet-confirm-actions {\n  display: flex;\n  gap: 10px;\n  padding: 4px;\n}\n\n.sheet-confirm-actions .mobile-button {\n  flex: 1;\n}\n\n.sheet-confirm-danger {\n  flex: 1;\n  height: 38px;\n  border: none;\n  border-radius: 10px;\n  background: var(--m-danger);\n  color: #fff;\n  font-size: 14px;\n  cursor: pointer;\n}\n\n.sheet-confirm-danger:disabled {\n  opacity: 0.5;\n}\n\n.chat-meta {\n  margin-top: 4px;\n  color: var(--m-text-tertiary);\n  font-size: 11px;\n}\n\n.chat-typing {\n  color: var(--m-text-tertiary);\n  font-size: 13px;\n  padding: 4px 2px;\n}\n\n.chat-inputbar {\n  display: flex;\n  gap: 8px;\n  padding: 10px 12px calc(env(safe-area-inset-bottom, 0px) + 10px);\n  border-top: 1px solid var(--m-border);\n  background: var(--m-bg);\n}\n\n.chat-input {\n  flex: 1;\n  min-width: 0;\n  min-height: 40px;\n  max-height: 120px;\n  /* Grow with the content (still bounded by min/max-height); browsers\n     without field-sizing support ignore this line and keep the old size. */\n  field-sizing: content;\n  padding: 9px 12px;\n  border: 1px solid var(--m-border);\n  border-radius: 10px;\n  background: var(--m-bg-input);\n  color: var(--m-text);\n  font: inherit;\n  font-size: 14.5px;\n  resize: none;\n  outline: none;\n}\n\n.chat-input:focus {\n  border-color: var(--m-accent);\n}\n\n.chat-send {\n  flex: none;\n  align-self: flex-end;\n  height: 40px;\n  padding: 0 16px;\n  border: none;\n  border-radius: 10px;\n  background: var(--m-accent);\n  color: #fff;\n  font-size: 14px;\n  cursor: pointer;\n}\n\n.chat-send:disabled {\n  opacity: 0.5;\n}\n\n.chat-load-older {\n  align-self: center;\n  margin: 4px 0;\n  border: none;\n  background: transparent;\n  color: var(--m-text-secondary);\n  font-size: 13px;\n  cursor: pointer;\n  padding: 6px 10px;\n}\n\n/* Touch surfaces have no hover, so keyboard focus must be fully visible.\n   One shared ring keeps every interactive control consistent and readable\n   on both palettes. */\n.mobile-row:focus-visible,\n.mobile-button:focus-visible,\n.mobile-new:focus-visible,\n.chat-send:focus-visible,\n.chat-chip:focus-visible,\n.chat-msg-toggle:focus-visible,\n.chat-load-older:focus-visible,\n.chat-disclosure-head:focus-visible,\n.sheet-option:focus-visible,\n.sheet-confirm-danger:focus-visible,\n.sheet-toggle-switch:focus-visible,\n.chat-input:focus-visible {\n  outline: none;\n  box-shadow: 0 0 0 2px var(--m-bg), 0 0 0 4px var(--m-accent);\n}\n\n/* \u2500\u2500 chat context usage chip (chat-tools row) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.chat-context {\n  flex: none;\n  align-self: center;\n  padding: 2px 10px;\n  border: 1px solid var(--m-border);\n  border-radius: 999px;\n  background: color-mix(in srgb, var(--m-text-tertiary) 10%, transparent);\n  color: var(--m-text-tertiary);\n  font-size: 11px;\n  line-height: 1.6;\n  white-space: nowrap;\n}\n\n.chat-context-warn {\n  border-color: var(--m-danger);\n  background: color-mix(in srgb, var(--m-danger) 14%, transparent);\n  color: var(--m-danger);\n}\n\n/* \u2500\u2500 display sheet toggle rows \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.sheet-toggle-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px 8px;\n  border-bottom: 1px solid var(--m-border);\n}\n\n.sheet-toggle-row:last-child {\n  border-bottom: none;\n}\n\n.sheet-toggle-copy {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.sheet-toggle-title {\n  font-size: 14px;\n}\n\n.sheet-toggle-desc {\n  color: var(--m-text-tertiary);\n  font-size: 12px;\n  line-height: 1.4;\n}\n\n.sheet-toggle-switch {\n  position: relative;\n  flex: none;\n  width: 44px;\n  height: 26px;\n  border: none;\n  border-radius: 999px;\n  background: var(--m-border);\n  cursor: pointer;\n  transition: background-color 0.15s ease;\n}\n\n.sheet-toggle-switch-on {\n  background: var(--m-accent);\n}\n\n.sheet-toggle-switch-knob {\n  position: absolute;\n  top: 3px;\n  left: 3px;\n  width: 20px;\n  height: 20px;\n  border-radius: 50%;\n  background: #fff;\n  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.2);\n  transition: transform 0.15s ease;\n}\n\n.sheet-toggle-switch-on .sheet-toggle-switch-knob {\n  transform: translateX(18px);\n}\n\n/* Accessibility: collapse every interaction/enter animation for\n   reduced-motion users; surface layout itself stays static. */\n@media (prefers-reduced-motion: reduce) {\n  .mobile-theme-toggle,\n  .mobile-back,\n  .mobile-row,\n  .mobile-button,\n  .mobile-new,\n  .chat-send,\n  .chat-chip,\n  .chat-msg-toggle,\n  .chat-load-older,\n  .chat-disclosure-head,\n  .chat-disclosure-caret,\n  .chat-msg-pending .chat-msg-text::after,\n  .sheet-backdrop,\n  .sheet,\n  .sheet-option,\n  .sheet-confirm-danger,\n  .sheet-toggle-switch,\n  .sheet-toggle-switch-knob,\n  .chat-input {\n    animation: none;\n    transition: none;\n  }\n}\n";
